"""The committed results are regenerated byte for byte from code + data: no number in results/ is hand-written."""

import json
from pathlib import Path

import pytest

from eval import run
from eval.systems import OFFLINE

ROOT = Path(__file__).resolve().parents[1]
RESULTS = ROOT / "results"
OFFLINE_RESULTS = (
    sorted(p for p in RESULTS.glob("*.json") if (p.stem.rsplit("_", 1)[0] in OFFLINE)) if RESULTS.exists() else []
)


def test_offline_results_are_committed_for_their_splits() -> None:
    names = {p.name for p in OFFLINE_RESULTS}
    assert names == {f"{system}_{split}.json" for system, splits in OFFLINE.items() for split in splits}


@pytest.mark.parametrize("path", OFFLINE_RESULTS, ids=lambda p: p.stem)
def test_committed_offline_results_are_reproducible(path: Path) -> None:
    system, split = path.stem.rsplit("_", 1)
    results, errors = run.evaluate(system, split, ROOT / "data")
    results_path, errors_path = run.output_paths(RESULTS, system, split)
    assert results == results_path.read_bytes()
    assert errors == errors_path.read_bytes()


@pytest.mark.parametrize("path", OFFLINE_RESULTS, ids=lambda p: p.stem)
def test_results_carry_the_required_metrics(path: Path) -> None:
    doc = json.loads(path.read_bytes())
    m = doc["metrics"]
    for key in (
        "dangerous_approval_rate",
        "unjustified_pend_rate",
        "decision_accuracy",
        "criterion_accuracy",
        "evidence_validity",
    ):
        assert set(m[key]) == {"k", "n", "value", "ci95"}
    assert {"cost_usd_per_case", "latency_ms_per_case"} <= set(m["usage"])
    assert len(doc["data_digest"]) == 64


def test_main_writes_results_and_errors(tmp_path: Path) -> None:
    assert run.main(["--system", "rules_baseline", "--split", "dev", "--out", str(tmp_path)]) == 0
    results, errors = run.output_paths(tmp_path, "rules_baseline", "dev")
    assert json.loads(results.read_bytes())["metrics"]["n_cases"] == 100
    for line in errors.read_text().splitlines():
        rec = json.loads(line)
        assert rec["predicted"] != rec["expected"] or rec["criteria"] or rec["invalid_evidence"] or rec["error"]


def test_comparison_table_is_generated_from_the_committed_results() -> None:
    from eval import report

    assert report.render(RESULTS) == (RESULTS / "comparison.md").read_text(encoding="utf-8")
